<?php require __DIR__.'/_start.php'; ?>
<section class="admin-card"><form method="get" action="<?= e(url('admin/customers')) ?>" class="filter-row"><div><label for="q">Müşteri ara</label><input id="q" class="form-control" name="q" value="<?= e($search) ?>" placeholder="Ad, e-posta veya telefon" maxlength="100"></div><div><label for="active">Hesap durumu</label><select id="active" name="active" class="form-select"><option value="">Tümü</option><option value="1" <?= $active==='1' ? 'selected' : '' ?>>Aktif</option><option value="0" <?= $active==='0' ? 'selected' : '' ?>>Pasif</option></select></div><button type="submit" class="btn btn-lumera">Filtrele</button><a class="btn btn-outline-dark" href="<?= e(url('admin/customers')) ?>">Temizle</a></form><p class="muted mt-3"><?= $count ?> müşteri · Sayfa <?= $number ?></p>
<?php if(!$customers): ?><p class="empty-state">Aramanıza uygun müşteri bulunamadı.</p><?php else: ?><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Ad soyad</th><th>İletişim</th><th>Durum</th><th>İşlem</th></tr></thead><tbody><?php foreach($customers as $customer): ?><tr><td><?= e($customer['name']) ?></td><td><?= e($customer['email']) ?><small><?= e($customer['phone'] ?? '') ?></small></td><td><?= $customer['is_active'] ? 'Aktif' : 'Pasif' ?></td><td><a href="<?= e(url('admin/customers?'.http_build_query(['id'=>$customer['id'],'q'=>$search,'active'=>$active,'p'=>$number]))) ?>" class="btn btn-sm btn-outline-dark">Detay / geçmiş</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<nav class="d-flex gap-3" aria-label="Müşteri sayfaları"><?php if($number>1): ?><a href="<?= e(url('admin/customers?'.http_build_query(['q'=>$search,'active'=>$active,'p'=>$number-1]))) ?>">← Önceki</a><?php endif ?><?php if($number*25<$count): ?><a href="<?= e(url('admin/customers?'.http_build_query(['q'=>$search,'active'=>$active,'p'=>$number+1]))) ?>">Sonraki →</a><?php endif ?></nav></section>
<?php if($detail): ?><section class="admin-card mt-4"><h2><?= e($detail['name']) ?></h2><p><?= e($detail['email']) ?> · <?= e($detail['phone'] ?? 'Telefon belirtilmedi') ?></p><p>Kayıt: <?= e(date('d.m.Y',strtotime($detail['created_at']))) ?></p><form method="post" action="<?= e(url('admin/customers/status')) ?>"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$detail['id'] ?>"><input type="hidden" name="active" value="<?= $detail['is_active'] ? '0' : '1' ?>"><button type="submit" class="btn btn-outline-dark"><?= $detail['is_active'] ? 'Hesabı pasife al' : 'Hesabı aktifleştir' ?></button></form><p class="muted mt-2">Pasife alma yeni girişleri ve randevu oluşturmayı engeller; geçmiş ve mevcut randevular korunur.</p><h3 class="mt-4">Randevu geçmişi</h3><?php $appointments=$history; $showActions=false; require __DIR__.'/_appointments.php'; ?></section><?php endif ?>
